function staleLeaseDecision_(status,started,attempt,max,needed){if(String(status)!=='running')return'ignore';const d=parseDateish_(started),age=d?(now_()-d)/60000:999999;if(age<15)return'active';if(!needed||Number(attempt||0)>=Number(max||JC.RETRIES))return'cancel';return'requeue';}
function recoverStaleQueueLeases_(){const s=SH_(JC.S.Q);if(s.getLastRow()<2)return{requeued:0,cancelled:0};const v=s.getRange(2,1,s.getLastRow()-1,16).getValues();let rq=0,cx=0;for(let i=0;i<v.length;i++){if(String(v[i][3]||'')!=='running')continue;const app=String(v[i][1]||''),type=String(v[i][2]||''),payload=v[i][13]?(()=>{try{return JSON.parse(v[i][13]);}catch(e){return{};}})():{},needed=queueJobFresh_(app,type,payload,String(v[i][5]||'')),act=staleLeaseDecision_(v[i][3],v[i][9],v[i][6],v[i][7],needed),row=i+2;if(act==='requeue'){s.getRange(row,4).setValue('queued');s.getRange(row,9).setValue(now_());s.getRange(row,10).clearContent();s.getRange(row,12).setValue('STALE_LEASE_RECOVERED');s.getRange(row,13).setValue('Running lease exceeded 15 minutes; safely requeued after semantic freshness check.');s.getRange(row,16).setValue(now_());rq++;}else if(act==='cancel'){s.getRange(row,4).setValue('cancelled');s.getRange(row,11).setValue(now_());s.getRange(row,12).setValue('STALE_LEASE_CANCELLED');s.getRange(row,13).setValue('Running lease exceeded 15 minutes and work is no longer current or attempts exhausted.');s.getRange(row,16).setValue(now_());cx++;}}return{requeued:rq,cancelled:cx};}
