function criticalSchemaContracts_(){return[[JC.S.A,['Application ID','Decision','Status','JD Completeness %','JD Snapshot Status','Blocker Category','Exact Input Needed','Resume Review Decision','ATS QA Status','State Consistency']],[JC.S.SRC,sourceRequiredHeaders_().concat(['Duplicate Application ID','Canonical URL'])],[JC.S.ACT,['Record ID','Record Type','Action Type','Exact Action Needed','Workflow Status','Your Response / Artifact Link','Response Status','Last Updated']],[JC.S.JD,['JD Snapshot ID','Application ID','Completeness %','Snapshot Status']],[JC.S.MAP,['Application ID','JD Requirement','Evidence Strength','Candidate Evidence']],[JC.S.RR,['Resume Version ID','Application ID','QA Status','Review Decision','Used to Apply?','Immutable After Submission?']],[JC.S.RV,['Application ID','ATS QA','Review Decision']],[JC.S.Q,['Queue Job ID','Application ID','Worker Type','Status','Idempotency Key','Attempts','Max Attempts','Next Retry At','Started At','Finished At','Error Code','Error Detail','Payload Ref','Created At','Updated At']],[JC.S.COST,['Timestamp','Application ID','Worker','Task','Provider','Model','Estimated USD','Queue Job ID']],['__Worker State',['Key','Value','Updated At','Notes']],[P12.SHEETS.HEALTH,['Component','Status','Circuit State','Error Code','Version']],[P12.SHEETS.REG,['Run ID','Suite Version','Test ID','Status']],[P12.SHEETS.JDART,['Application ID','JD Snapshot ID','Drive File ID','Status']],[P12.SHEETS.ART,['Application ID','Resume Version ID','Drive File ID','Status']],['__Failure Learning',['Defect ID','Status','Owner','Learning / Reuse Rule']]];}
