function activeQueueAudit_(){const s=SH_(JC.S.Q);if(s.getLastRow()<2)return{running:0,queued:0,staleRunning:0,invalidQueued:0,pendingPdf:0};const v=s.getRange(2,1,s.getLastRow()-1,16).getValues();let running=0,queued=0,stale=0,invalid=0,pdf=0;for(const r of v){const st=String(r[3]||''),type=String(r[2]||''),app=String(r[1]||'');if(st==='running'){running++;if(staleLeaseDecision_(st,r[9],r[6],r[7],true)!=='active')stale++;}if(st==='queued'){queued++;let p={};try{p=r[13]?JSON.parse(r[13]):{};}catch(e){invalid++;continue;}if(type===JC.W.PDF)pdf++;else if(!queueJobFresh_(app,type,p,String(r[5]||'')))invalid++;}}return{running:running,queued:queued,staleRunning:stale,invalidQueued:invalid,pendingPdf:pdf};}
function blockerInvariantAudit_(){const a=SH_(JC.S.A),m=hm_(a),v=a.getDataRange().getDisplayValues(),act=SH_(JC.S.ACT),am=hm_(act),av=act.getLastRow()>1?act.getRange(2,1,act.getLastRow()-1,act.getLastColumn()).getDisplayValues():[],ids={};av.forEach(r=>{if(r[am['Record ID']-1])ids[String(r[am['Record ID']-1])]=1;});const missing=[];for(let i=1;i<v.length;i++){const id=String(v[i][m['Application ID']-1]||''),decision=String(v[i][m['Decision']-1]||''),bl=String(v[i][m['Blocker Category']-1]||''),ex=String(v[i][m['Exact Input Needed']-1]||'');if(id&&decision==='Apply'&&bl&&ex&&!ids[id])missing.push(id);}return missing;}
